export function sbsGroundAssetByKey(key) {
  return HMH_LEVEL_ONE_SBS_GROUND.assets.find((asset) => asset.key === key) ?? null;
}

export function sbsGroundAssetsForRole(role) {
  const keys = HMH_LEVEL_ONE_SBS_GROUND.roles?.[role] ?? [];
  return keys.map((key) => sbsGroundAssetByKey(key)).filter(Boolean);
}
